export const brandLogoHeaderSrcSet = [400, 600, 800].map((w) => `/images/branding/mpho-madi-logo-header-${w}w.png ${w}w`).join(', ')
export const brandLogoHeaderSizes = '(min-width: 1024px) 201px, (min-width: 768px) 164px, 176px'
// Reversed (all-white) mark for dark grounds — the navy footer. Using it
